/* v1.7 approved patient/doctor simplifications, composed inside the app scope. */
const V17={queueY:0,detailTab:'timeline',dirty:false,groupDirty:false,batch:[],uploadContext:null,qlqPhase:null,chat:null,archiveType:'全部',next:null};
function ensure17(){for(let k of ['queries','appointments','seenReports','confirmedReports','followups','deferred','eventDrafts'])S()[k]??={};}
function nowStudy(){return S().stage===5?(S().followNode==='efs'?Schedule.month(S().treatmentStart,S().followMonth):S().followNode==='postop'?Schedule.month(S().tasks.surgeryDate,6):Schedule.addDays(S().treatmentStart,167)):Schedule.date(S())||N.today()}
function plainName(t){return String(t).replace(/QLQ 量表|QLQ量表|模拟量表/g,'生活质量问卷').replace(/EPclin/g,'基因检测').replace(/C(\d+)\s*D(\d+)/g,'第$1周期 · 第$2天').replace(/C(\d+)/g,'第$1周期').replace(/EFS · 第/g,'治疗开始后第').replace(/今天是达尔西利停药日/g,'今天不服用达尔西利');}
const render17base=render;render=()=>{ensure17();render17base();let host=$('#patient');let walker=document.createTreeWalker(host,NodeFilter.SHOW_TEXT);while(walker.nextNode())if(!['TEXTAREA','SCRIPT','STYLE'].includes(walker.currentNode.parentElement?.tagName))walker.currentNode.textContent=plainName(walker.currentNode.textContent);};
const close17base=close;close=side=>{close17base(side);};
const pMore17base=pMore;pMore=()=>pMore17base().replace('data-value="screen"','data-value="archive"');
function archive(){let all=S().reports.filter(r=>V17.archiveType==='全部'||r.type===V17.archiveType).slice().reverse();return head('我的研究资料')+`<div class="tabs">${['全部',...Object.keys(N.docs).filter(k=>S().reports.some(r=>r.type===k))].map(k=>btn(k==='全部'?k:N.docs[k],'archiveFilter',k,V17.archiveType===k?'active':'')).join('')}</div>${all.map(r=>`<div class="card">${link(r.name,'report',r.id)}<small>${esc(r.examDate||'检查日期待确认')} · ${esc(r.phase||'既有研究资料')}</small></div>`).join('')||'<div class="empty">还没有上传资料</div>'}`;}
function uploadTypes(){return V17.uploadContext?.types||TrialUI.reportKinds(S().stage,reportContext)}
function uploadWizard(context){V17.uploadContext=context||{types:TrialUI.reportKinds(S().stage,reportContext),phase:stageLabel()};V17.batch=[];drawBatch();}
function drawBatch(){let kinds=uploadTypes();modal('上传医疗资料',`<p>可一次选择多份图片或 PDF。检查资料归属后一起提交。</p><input id="batchFiles" aria-label="批量选择医疗资料" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf"><small>每份不超过2MB。真实文件按文件名辅助归类，请核对。</small><div class="action-row">${btn('使用本次模拟资料','batchSample','','secondary')}</div>${V17.batch.map((r,i)=>`<div class="card"><b>${esc(r.name)}</b>${select('资料类型','batchType'+i,['请确认类型',...kinds.map(k=>N.docs[k])],N.docs[r.type]||'请确认类型')}${field('检查日期（不清楚可留空）','batchDate'+i,r.examDate||'','date')}${btn('移除','batchRemove',i,'text-btn')}</div>`).join('')}${V17.batch.length?btn('确认提交 '+V17.batch.length+' 份资料','batchCommit','','primary wide'):''}`);}
function batchCapture(){V17.batch.forEach((r,i)=>{let val=formValue('batchType'+i);r.type=Object.keys(N.docs).find(k=>N.docs[k]===val)||'';r.examDate=formValue('batchDate'+i);});}
function pUploadHub(){let kinds=TrialUI.reportKinds(S().stage,reportContext),have=kinds.filter(k=>S().reports.some(r=>r.type===k));return head('上传医疗资料','p',S().stage===0?'screen':'tasks')+`<div class="card"><h3>本次资料 ${have.length}/${kinds.length}</h3>${kinds.map(k=>row(N.docs[k],have.includes(k)?'已收到':'待补充')).join('')}${btn('一次上传多份资料','batchOpen','','primary wide')}</div>`;}
pReports=pUploadHub;
function queryPanel(side){let qs=Object.values(S().queries).filter(q=>q.status!=='已确认');if(!qs.length)return '';return `<div class="card"><h3>${side==='p'?'需要补充的资料':'资料补充任务'}</h3>${qs.map(q=>`<div class="subtask"><b>${esc(q.title)}</b><p>${esc(q.note)}</p><small>${q.status}</small>${side==='p'?(q.status==='待补充'?btn('补充上传','queryUpload',q.id,'secondary wide'):''):btn('查看并核对','queryReview',q.id,'secondary wide')}</div>`).join('')}</div>`;}
const pScreen17base=pScreen;pScreen=()=>pScreen17base()+queryPanel('p');
const pPreparation17base=pPreparation;pPreparation=()=>head('临床试验陪伴')+`<div class="hint neutral">导入期 · 入组准备</div>${qlqBundleCard('基线')}<div class="card"><h3>${S().introConfirmed?'首次服药日期：'+S().firstDose:'等待研究医生确认首次服药日期'}</h3><p>问卷可独立填写，不影响日期确认。</p></div>`+queryPanel('p');
function qlqBundleCard(phase){return `<div class="card">${task('本次生活质量问卷',phase+' · 已完成 '+qDone(phase)+'/2','qlqBundle',phase,qDone(phase)===2)}</div>`;}
baselinePending=()=>'';
function qlqEligible(phase){if(phase==='基线')return S().stage>=1;if(phase==='术后半年')return !!S().surgeryConfirmed&&S().followNode==='postop';let c=+phase[1];return S().stage>4||S().stage===4&&(S().cycle>c||S().cycle===c&&S().day>=28);}
Schedule.qlqOpen=(s,key)=>!!s.qlq[key]||(key.startsWith('基线')?s.stage>=1:key.startsWith('术后半年')?!!s.surgeryConfirmed&&s.followNode==='postop':s.stage>4||s.stage===4&&(s.cycle>+key[1]||s.cycle===+key[1]&&s.day>=28));
function bundleOpen(phase){V17.qlqPhase=phase;let key=['A','B'].find(k=>!S().qlq[phase+'-'+k]);if(key)return openQLQ(phase+'-'+key);modal('本次问卷已完成',`<p>${phase} · 两份均已提交</p>${['A','B'].map(k=>link('查看问卷 '+k,'openQLQ',phase+'-'+k)).join('')}`);}
const submitQLQ17base=actions.submitQLQ;actions.submitQLQ=key=>{submitQLQ17base(key);if(!S().qlq[key])return;let phase=key.split('-')[0];modal(qDone(phase)===2?'本次问卷已完成':'第一份已提交',`<p>已完成 ${qDone(phase)}/2</p>${qDone(phase)<2?btn('继续第二份','qlqBundle',phase,'primary wide'):btn('返回任务','close','','primary wide')}`);};
function directMed(t,day,future){let key=TrialUI.medKey(S(),t.value,day),r=S().meds[key];return `<div class="direct-med"><h3>${t.title}</h3><small>${future?'尚未到这一天':r?'已记录：'+r.status+(r.backfill?' · 补录':''):'请记录实际服药情况'}</small>${future?'':r?btn('修改','editDirectMed',t.value+'|'+day,'text-btn'):`<div class="choice-row">${['已服用','未服用','不确定'].map(st=>btn(st,'directMed',t.value+'|'+day+'|'+st,'secondary')).join('')}</div>`}${r&&r.status!=='已服用'?btn(r.reason?'查看/修改说明':'补充说明（选填）','medReason',t.value+'|'+day,'text-btn'):''}</div>`;}
function pendingPanel(){let s=S(),items=[];for(let ph of ['基线','C3','C6'])if(qlqEligible(ph)&&qDone(ph)<2)items.push(task(ph+'生活质量问卷',qDone(ph)+'/2 已完成，随时续填','qlqBundle',ph));if(s.stage>=2&&s.stage<=4){for(let d=1;d<s.day;d++){let missing=Schedule.tasks(s,d).filter(t=>!t.done&&!t.id.startsWith('C')&&!t.weekly);if(missing.some(t=>t.id.startsWith('med-')))items.push(link('第'+d+'天用药记录 · 待补录','pickDay',d,'pill'));if(missing.some(t=>['biopsy','slides'].includes(t.id)))items.push(link('第'+d+'天检查 · 等待重新安排','reschedule','D'+d,'calendar'));}}
for(let v of Schedule.visits(s)){let ap=s.appointments[v.date],due=ap?.date||v.date;if(due<nowStudy()&&!s.tasks['visit-'+v.date])items.push(link(due+'复查 · '+(s.deferred[v.date]?'已申请改期，等待更新':'等待重新安排'),s.deferred[v.date]?'waitingVisit':'reschedule',v.date,'calendar'));}
return (items.length?`<details class="card pending-list"><summary>还有待完成事项 · ${items.length}</summary>${items.join('')}</details>`:'')+queryPanel('p');}
function aeFollowTasks(){return S().aes.filter(a=>!a.closed).map(a=>`<div class="card">${task(a.name+'后续情况','告诉我们是否就医、如何处置及现在感觉','aeFollow',a.id,!!a.external)}${a.external?'<small>已反馈：'+esc(a.external.outcome)+'；变化时可再次补充。</small>':''}</div>`).join('');}
const pTasks17base=pTasks;pTasks=()=>{let s=S();if(s.stage===0)return pScreen();if(s.stage===1)return pPreparation();if(s.stage===5)return pLongFollow()+pendingPanel()+aeFollowTasks();let day=pickedDay??s.day,future=day>s.day,ts=Schedule.tasks(s,day),qs=ts.filter(t=>t.action==='openQLQ');return head('临床试验陪伴')+expertHero('今天，也有人陪着您',stageLabel())+dayCalendar()+`<div class="card"><div class="cx-cardHead"><h3>第${day}天 · ${day===s.day?'今日事项':'研究安排'}</h3><small>${ts.filter(t=>t.done).length}/${ts.length}</small></div>${Schedule.complete(s,day)?'<div class="daily-badge">✦ 当日任务已完成</div>':''}${ts.filter(t=>t.action!=='openQLQ').map(t=>t.action==='med'?directMed(t,day,future):t.rest?`<div class="rest-task"><h3>今天不服用达尔西利</h3><p>来曲唑仍按处方继续。</p>${t.done?'<span>已知晓</span>':btn('我知道了','restQuick',day,'secondary') }</div>`:t.weekly?weeklyRows(day,future,t.done):chemoTask(plainName(t.title),t.hint||'查看本次安排',t.action,t.value,t.done,future)).join('')}</div>${qs.length?qlqBundleCard('C'+s.cycle):''}${pendingPanel()}${aeFollowTasks()}${askAssistant()}`;};
const pLong17base=pLongFollow;pLongFollow=()=>{let html=pLong17base();html=html.replace(/<button class="task-row"[^>]*data-action="openQLQ"[\s\S]*?<\/button>/g,'');return html+(S().followNode==='postop'?qlqBundleCard('术后半年'):'');};
const sampleArrangement={time:'09:00',place:'研究门诊 A区 2层服务台（演示地点）',prep:'携带身份证明、既往报告及用药清单；具体检查要求以研究团队通知为准。'};
education=k=>{let c=educationContent[k]||educationContent.journey;modal(c[0],`<div class="hint neutral">以下为演示安排，后续替换</div>${row('时间',(Schedule.date(S(),S().stage<4?14:S().day)||N.today())+' '+sampleArrangement.time)}${row('地点',sampleArrangement.place)}<p>${sampleArrangement.prep}</p><details><summary>查看办理步骤</summary><p style="white-space:pre-line">${esc(c[1])}</p></details>${['biopsy','slides','blood'].includes(k)?btn(S().tasks[taskKey(k)]?'已完成':'已完成','educationDone',k,'primary wide'):''}${btn('需要帮助','helpTask',k,'secondary wide')}`);};
function visitPage(id){let ap=S().appointments[id]||{date:id,time:sampleArrangement.time,place:sampleArrangement.place,prep:sampleArrangement.prep,checks:['化验','影像','取药']},done=S().tasks['visit-'+id],rs=S().reports.filter(r=>r.visitId===id);modal('本次复查',`<div class="hint neutral">${ap.demo===false?'医生已确认安排':'演示安排 · 后续替换'}</div>${row('当前进度',S().visitStatus?.[id]||'尚未反馈')}${row('时间',ap.date+' '+ap.time)}${row('地点',ap.place)}<p>本次：${ap.checks.join('、')}</p><details><summary>准备事项</summary><p>${esc(ap.prep)}</p></details><h3>本次资料 ${rs.length} 份</h3>${btn('一起上传化验、影像和处方','visitUpload',id,'secondary wide')}${rs.map(r=>link(r.name,'report',r.id)).join('')}<div class="choice-row">${['已复查','尚未复查','等待报告'].map(st=>btn(st,'visitStatus',id+'|'+st,done===st?'primary':'secondary')).join('')}</div>${['C3','C6'].filter(qlqEligible).filter(ph=>qDone(ph)<2).map(ph=>btn('继续填写'+ph+'问卷','qlqBundle',ph,'text-btn')).join('')}`);}
function appointmentForm(id){let ap=S().appointments[id]||{date:id||Schedule.visits(S())[0]?.date||N.today(),...sampleArrangement,checks:['化验','影像','取药']};modal('安排复诊',field('日期','apptDate',ap.date,'date')+field('时间','apptTime',ap.time,'time')+field('地点','apptPlace',ap.place)+`<div class="check-options">${['化验','影像','取药','穿刺','抽血'].map(x=>`<label><input type="checkbox" name="apptCheck" value="${x}" ${ap.checks.includes(x)?'checked':''}>${x}</label>`).join('')}</div>`+textfield('准备说明','apptPrep',ap.prep)+btn('保存并同步患者任务','saveAppointment',id||ap.date,'primary wide'),'d');}
const follow17base=actions.followForm;actions.followForm=key=>{let prev=Object.values(S().followups).at(-1);if(!prev)return follow17base(key);modal('本次随访 · 确认变化',`<div class="hint neutral">上次治疗情况：${esc(prev.treatment)}</div>${select('后续治疗有变化吗？','treatmentChanged',['请选择','无变化','有变化','不确定'])}<div id="treatmentChanges" hidden>${textfield('变化详情','followTreatment','')}</div>${select('上次随访后有住院或被告知复发/进展吗？','eventChanged',['请选择','没有','有','不确定'])}<div id="eventChanges" hidden>${textfield('情况及日期','followDetails','')}</div>${btn('确认并提交','saveFollowChanges',key,'primary wide')}`);};
Object.assign(actions,{
 archiveFilter:k=>{V17.archiveType=k;go('p','archive')},batchOpen:()=>uploadWizard(),batchSample:()=>{batchCapture();for(let type of uploadTypes())if(!V17.batch.some(r=>r.type===type)){let r=N.sampleReport(type);r.id='R'+Date.now()+type;r.text=sampleContent(type);r.examDate=nowStudy();V17.batch.push(r)}drawBatch()},batchRemove:i=>{batchCapture();V17.batch.splice(+i,1);drawBatch()},
 batchCommit:()=>{batchCapture();if(!V17.batch.length||V17.batch.some(r=>!r.type))return notify('请确认每份资料类型');let ctx=V17.uploadContext||{},rows=V17.batch.filter(r=>!S().reports.some(x=>x.name===r.name&&x.data&&x.data===r.data)).map(r=>({...r,date:N.time(),phase:ctx.phase||stageLabel(),visitId:ctx.visitId,queryId:ctx.queryId,aeId:ctx.aeId,followKey:r.type==='followup'?followKey():undefined}));let n=S().reports.length;S().reports.push(...rows);try{N.save()}catch{S().reports.splice(n);return notify('本地空间不足，请减少文件或压缩图片后重试')}for(let r of rows)for(let i=0;i<criteria.length;i++)if(criteria[i][2]===r.type)delete S().criteriaReview?.[i];if(ctx.queryId){S().queries[ctx.queryId].status='已补交，待医生确认';S().queries[ctx.queryId].reportIds=rows.map(r=>r.id)}close('p');if(ctx.aeId){aeFollow(ctx.aeId)}else if(ctx.queryId){pPage=S().stage===0?'screen':'tasks'}else if(ctx.visitId){visitPage(ctx.visitId)}else pPage=S().stage===0?'screen':'tasks';save('患者批量提交 '+rows.length+' 份资料','患者');notify(rows.length?'资料已收到，原有文件保留':'这些文件已上传，无需重复提交');V17.batch=[];},
 upload:type=>uploadWizard({types:[type],phase:stageLabel()}),queryUpload:id=>{let q=S().queries[id];uploadWizard({types:q.type?[q.type]:['record','baseline','lab','imaging'],queryId:id,phase:'筛选补充'})},
 directMed:v=>{let [drug,ds,status]=v.split('|'),day=+ds;if(day>S().day||!Schedule.tasks(S(),day).some(t=>t.action==='med'&&t.value===drug))return notify('这一天没有可记录的该药任务');S().meds[TrialUI.medKey(S(),drug,day)]={status,time:N.time(),reason:'',backfill:day<S().day,date:Schedule.date(S(),day)};save('用药记录：'+status+(day<S().day?'（补录）':''),'患者')},editDirectMed:v=>{let [drug,day]=v.split('|');modal('修改当天用药记录',`<div class="choice-row">${['已服用','未服用','不确定'].map(st=>btn(st,'editMedSave',v+'|'+st,'secondary')).join('')}</div>`)},editMedSave:v=>{close();actions.directMed(v)},medReason:v=>{let [drug,day]=v.split('|');modal('补充说明（选填）',textfield('原因或说明','optionalReason',S().meds[TrialUI.medKey(S(),drug,+day)]?.reason||'')+btn('保存','saveMedReason',v,'primary wide'))},saveMedReason:v=>{let [drug,day]=v.split('|');S().meds[TrialUI.medKey(S(),drug,+day)].reason=formValue('optionalReason');close();save('补充用药说明','患者')},restQuick:v=>{actions.confirmRestDay(v)},qlqBundle:bundleOpen,education,
 helpTask:k=>{close();go('p','chat');$('#chatInput').value='我需要帮助完成'+(educationContent[k]?.[0]||'本次任务')},monthlyVisit:visitPage,visitUpload:id=>uploadWizard({types:['lab','imaging','outside'],visitId:id,phase:'每月复查'}),visitStatus:v=>{let[id,status]=v.split('|');S().tasks['visit-'+id]=status==='已复查'?'已复查':false;S().visitStatus??={};S().visitStatus[id]=status;N.log('本次复查反馈：'+status,'患者');render();visitPage(id)},reschedule:id=>{S().deferred[id]=true;save('患者申请重新安排：'+id,'患者');notify('已记录，请等待研究团队更新预约')},appointment:appointmentForm,
 saveAppointment:id=>{let date=formValue('apptDate','d'),time=formValue('apptTime','d'),place=formValue('apptPlace','d'),checks=[...document.querySelectorAll('[name="apptCheck"]:checked')].map(e=>e.value);if(!date||!time||!place||!checks.length)return notify('请补充日期、时间、地点及检查项目');S().appointments[id]={date,time,place,checks,prep:formValue('apptPrep','d'),demo:false};delete S().deferred[id];close('d');save('更新预约并同步患者任务 '+date,'研究医生');notify('患者端已更新预约，不需要重复发送安排')},
 saveFollowChanges:key=>{let tc=formValue('treatmentChanged'),ec=formValue('eventChanged'),tx=formValue('followTreatment'),det=formValue('followDetails'),prev=Object.values(S().followups).at(-1);if(tc==='请选择'||ec==='请选择'||tc==='有变化'&&!tx||ec==='有'&&!det)return notify('请确认两项变化，并补充发生变化的内容');S().followups[key]={treatment:tc==='无变化'?prev.treatment:tc==='不确定'?'不确定，待核':tx,status:ec==='没有'?'上次随访后未新增住院或复发/进展情况':ec,details:det,date:N.time(),previousTreatment:prev.treatment};close();save('提交本次随访变化','患者')}
});
// One stable appointment ID links the doctor arrangement, calendar and patient report bundle.
const tasks17base=Schedule.tasks;Schedule.tasks=(s,d=s.day)=>{let out=tasks17base(s,d).filter(t=>!t.id.startsWith('visit-'));for(let v of Schedule.visits(s)){let ap=s.appointments?.[v.date];if((ap?.date||v.date)===Schedule.date(s,d))out.push({id:'visit-'+v.date,title:'本月复查',action:'monthlyVisit',value:v.date,hint:(ap?.time||sampleArrangement.time)+' · '+(ap?.place||sampleArrangement.place),done:s.tasks['visit-'+v.date]==='已复查'||s.tasks['visit-'+v.date]===true});}return out};
const prepReport17=reportView;reportView=(id,side='p')=>{if(side==='d'){S().seenReports[id]=N.time();N.save()}prepReport17(id,side)};
actions.doctorReport=id=>reportView(id,'d');actions.report=id=>reportView(id,'p');
